import{_ as a,c as t,o as r,a9 as d}from"./chunks/framework.Bqk8xQPS.js";const b=JSON.parse('{"title":"NATS Queue Bridge","description":"Durable pull-based queues backed by NATS JetStream.","frontmatter":{"title":"NATS Queue Bridge","description":"Durable pull-based queues backed by NATS JetStream.","order":301530},"headers":[],"relativePath":"handbook/3_eco_system/queue_bridges/nats_queue_bridge.md","filePath":"handbook/3_eco_system/queue_bridges/nats_queue_bridge.md","lastUpdated":1775112854000}'),i={name:"handbook/3_eco_system/queue_bridges/nats_queue_bridge.md"};function l(s,e,o,n,u,c){return r(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="nats-queue-bridge" tabindex="-1">NATS Queue Bridge <a class="header-anchor" href="#nats-queue-bridge" aria-label="Permalink to “NATS Queue Bridge”">​</a></h1><p><code>@purista/nats-queue-bridge</code> provides a JetStream-backed queue bridge for teams that already operate NATS and want queue semantics without introducing Redis only for pull-based workloads.</p><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to “Capabilities”">​</a></h2><table tabindex="0"><thead><tr><th>feature</th><th>support</th></tr></thead><tbody><tr><td>Durability</td><td>✅ (JetStream streams + durable pull consumers)</td></tr><tr><td>Delayed delivery</td><td>✅ (scheduled stream with due-job release)</td></tr><tr><td>Dead-letter queue</td><td>✅ (dedicated DLQ streams per logical queue)</td></tr><tr><td>Lease extension</td><td>✅ (<code>working()</code> heartbeats + lease inspection)</td></tr><tr><td>Lease expiry recovery</td><td>✅ (ack timeout redelivery)</td></tr><tr><td>DLQ inspect / replay / purge</td><td>✅</td></tr></tbody></table><h2 id="safe-defaults" tabindex="-1">Safe defaults <a class="header-anchor" href="#safe-defaults" aria-label="Permalink to “Safe defaults”">​</a></h2><ul><li>JetStream is required. The bridge does not fall back to core NATS.</li><li>FIFO queue consumption and <code>prefetch: 1</code> are the intended defaults.</li><li>DLQ naming follows the standard PURISTA suffix resolution, so service health and queue metrics resolve the same target.</li><li>Short lease TTLs are honored by adjusting the queue consumer ack timeout, while long-running workers should still call <code>context.job.extendLease(...)</code>.</li></ul><h2 id="operational-notes" tabindex="-1">Operational notes <a class="header-anchor" href="#operational-notes" aria-label="Permalink to “Operational notes”">​</a></h2><ul><li>This bridge is best when the same platform already uses NATS for event traffic and wants one operational stack.</li><li>DLQ replay is bridge-managed, not a JetStream “magic queue replay” feature. Operators should inspect the failed payload and reason before redriving.</li><li>Scheduled jobs are stored separately from immediately runnable jobs, so delayed workloads do not block normal queue throughput.</li></ul><h2 id="related-links" tabindex="-1">Related links <a class="header-anchor" href="#related-links" aria-label="Permalink to “Related links”">​</a></h2><ul><li><a href="./">Queue bridges overview</a></li><li><a href="./../../2_building_business-logic/queue/">Queues overview</a></li><li><a href="./../eventbridges/nats.html">NATS event bridge</a></li></ul>',10)])])}const p=a(i,[["render",l]]);export{b as __pageData,p as default};
